CREATE OR REPLACE FUNCTION public.imp_lote_access(_id uuid) RETURNS void LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE l public.pesajes_cintas_lotes; BEGIN SELECT * INTO l FROM public.pesajes_cintas_lotes WHERE id=_id; IF l.imp_bobina_id IS NOT NULL AND (NOT public.user_sees_planta(auth.uid(),l.planta_corte_id) OR NOT public.can_edit_module(auth.uid(),'pesaje_cintas')) THEN RAISE EXCEPTION 'Sin permiso para cortes de esta planta' USING ERRCODE='42501'; END IF; END $$; REVOKE ALL ON FUNCTION public.imp_lote_access(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.imp_lote_access(uuid) TO authenticated;
DO $$ DECLARE p record; d text; BEGIN FOR p IN SELECT oid,proname FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN ('finalizar_lote_cintas','reabrir_lote_cintas','pc_set_orden_manual','pc_set_bobinador_nombre','pc_set_nombres_operativos','pc_set_personal_cortes','pc_set_bobinadora','actualizar_datos_operativos_lote_cintas','preparar_impresion_etiquetas') LOOP SELECT pg_get_functiondef(p.oid) INTO d; d:=replace(d,'BEGIN','BEGIN PERFORM public.imp_lote_access(_lote_id);'); IF p.proname='finalizar_lote_cintas' THEN d:=replace(d,'IF NOT COALESCE(v_lote.es_manual, false) AND v_lote.pesaje_bobina_madre_id IS NULL THEN','IF v_lote.imp_bobina_id IS NULL AND NOT COALESCE(v_lote.es_manual, false) AND v_lote.pesaje_bobina_madre_id IS NULL THEN'); END IF; EXECUTE d; END LOOP; SELECT pg_get_functiondef('public.pc_bajadas_rollo(text)'::regprocedure) INTO d; d:=replace(d,'l.estado <> ''anulado''','l.estado <> ''anulado'' AND (l.imp_bobina_id IS NULL OR public.user_sees_planta(v_uid,l.planta_corte_id))'); d:=replace(d,'c.estado = ''registrada''','c.estado = ''registrada'' AND (l.imp_bobina_id IS NULL OR public.user_sees_planta(v_uid,l.planta_corte_id))'); d:=replace(d,'l.estado = ''abierto'' LIMIT 1','l.estado = ''abierto'' AND (l.imp_bobina_id IS NULL OR public.user_sees_planta(v_uid,l.planta_corte_id)) LIMIT 1'); EXECUTE d; END $$;